const json = (s) => {try{return JSON.parse(s)}catch{return {}}};
async function contentFromD1(db){
 const [c,doc] = await Promise.all([
   db.prepare("SELECT kind,slug,name,status,category_slug,sort_order,content_json FROM catalog_entities WHERE status='active' AND kind IN ('program','destination','category') ORDER BY sort_order,name").all(),
   db.prepare("SELECT key,content_json FROM site_documents WHERE key IN ('testimonials','camp_memories','faq','site_settings')").all()
 ]);
 const rows=(c.results||[]).map(x=>({...x,data:json(x.content_json)}));
 const docs=Object.fromEntries((doc.results||[]).map(d=>[d.key,json(d.content_json)]));
 return {destinations:rows.filter(r=>r.kind==='destination'),categories:rows.filter(r=>r.kind==='category'),programs:rows.filter(r=>r.kind==='program'),testimonials:(docs.testimonials.items||[]).filter(x=>x.is_active!==false),memories:(docs.camp_memories.items||[]).filter(x=>x.is_active!==false&&x.image&&path(x.image)),faqs:Array.isArray(docs.faq)?docs.faq:[],about:docs.site_settings?.about_page||{}};
}
async function handleMedia(request,env,uuid){
 const u=new URL(request.url);
 const preset=['mobile','tablet','desktop'].includes(u.searchParams.get('preset'))?u.searchParams.get('preset'):'desktop';
 const row=await env.DB.prepare("SELECT m.object_key,m.mime_type,v.object_key AS variant_key,v.mime_type AS variant_type FROM media_assets m LEFT JOIN media_variants v ON v.media_id=m.id AND v.preset=? WHERE m.id=? AND m.is_public=1").bind(preset,uuid).first();
 if(!row)return new Response('Image not found',{status:404,headers:{'x-robots-tag':'noindex'}});
 let key=row.variant_key||row.object_key;
 let object=await env.MEDIA.get(key);
 if(!object && row.variant_key){key=row.object_key;object=await env.MEDIA.get(key);}
 if(!object)return new Response('Image unavailable',{status:404,headers:{'x-robots-tag':'noindex'}});
 return new Response(object.body,{headers:{'content-type':key===row.variant_key?(row.variant_type||'image/webp'):(row.mime_type||'image/webp'),'cache-control':'public, max-age=3600','x-content-type-options':'nosniff','x-robots-tag':'noindex'}});
}

